    input.push(line);
}).on("close", function () {
    let [N, M] = input[0].split(" ").map(Number);
​
    // 初始化图，所有距离默认设为 -1（表示无路径）
    let graph = Array.from({ length: N + 1 }, () => Array(N + 1).fill(-1));
    for (let i = 0; i <= N; i++) graph[i][i] = 0;
​
    // 使用 Map 离散化 ID
    let mp = new Map();
​
    // 读取投递站到客户的距离
    for (let i = 1; i <= N; i++) {
        let [id, distance] = input[i].split(" ").map(Number);
        mp.set(id, i);
        graph[0][i] = graph[i][0] = distance;
    }
​
    // 读取客户之间的距离
    for (let i = N + 1; i < N + 1 + M; i++) {
        let [start, end, distance] = input[i].split(" ").map(Number);
        graph[mp.get(start)][mp.get(end)] = distance;
        graph[mp.get(end)][mp.get(start)] = distance;
    }
​
    // Floyd-Warshall 算法计算最短路径
    for (let k = 0; k <= N; k++) {
        for (let i = 0; i <= N; i++) {
            for (let j = 0; j <= N; j++) {
                if (graph[i][k] === -1 || graph[k][j] === -1) continue;
                if (graph[i][j] === -1) graph[i][j] = graph[i][k] + graph[k][j];
                else graph[i][j] = Math.min(graph[i][j], graph[i][k] + graph[k][j]);
            }
        }
    }
​
    // 状态压缩 DP，dp[mask][cur] 表示访问 mask 对应的所有客户后，最后停在 cur 的最短路径
    let dp = Array.from({ length: 1 << N }, () => Array(N + 1).fill(Infinity));
    dp[0][0] = 0; // 从起点出发
​
    for (let mask = 0; mask < (1 << N); mask++) {
        for (let cur = 0; cur <= N; cur++) {
            if (dp[mask][cur] === Infinity) continue;
            for (let next = 0; next <= N; next++) {
                if (graph[cur][next] === -1) continue;
                if (next === 0) {
                    dp[mask][next] = Math.min(dp[mask][next], dp[mask][cur] + graph[cur][next]);
                } else {
                    let nextMask = mask | (1 << (next - 1));
                    dp[nextMask][next] = Math.min(dp[nextMask][next], dp[mask][cur] + graph[cur][next]);
                }
            }
        }
    }
​
    // 计算最终结果，遍历所有可能的终点
    let end = (1 << N) - 1;
    let res = Infinity;
    for (let i = 0; i <= N; i++) {
        if (dp[end][i] !== Infinity && graph[i][0] !== -1) {
            res = Math.min(res, dp[end][i] + graph[i][0]);
        }
    }
​
    // 输出结果
    console.log(res);
});
