import (
    "fmt"
    "math"
)
​
func main() {
    var N, M int
    fmt.Scan(&N, &M)
​
    // 初始化图，所有距离默认设为 -1（表示无路径）
    graph := make([][]int, N+1)
    for i := range graph {
        graph[i] = make([]int, N+1)
        for j := range graph[i] {
            graph[i][j] = -1
        }
    }
    for i := 0; i <= N; i++ {
        graph[i][i] = 0
    }
​
    // 使用 map 离散化 ID
    mp := make(map[int]int)
​
    // 读取投递站到客户的距离
    for i := 0; i < N; i++ {
        var id, distance int
        fmt.Scan(&id, &distance)
        mp[id] = i + 1
        graph[0][mp[id]] = distance
        graph[mp[id]][0] = distance
    }
​
    // 读取客户之间的距离
    for i := 0; i < M; i++ {
        var start, end, distance int
        fmt.Scan(&start, &end, &distance)
        graph[mp[start]][mp[end]] = distance
        graph[mp[end]][mp[start]] = distance
    }
​
    // Floyd-Warshall 算法计算最短路径
    for k := 0; k <= N; k++ {
        for i := 0; i <= N; i++ {
            for j := 0; j <= N; j++ {
                if graph[i][k] == -1 || graph[k][j] == -1 {
                    continue
                }
                if graph[i][j] == -1 {
                    graph[i][j] = graph[i][k] + graph[k][j]
                } else {
                    graph[i][j] = min(graph[i][j], graph[i][k]+graph[k][j])
                }
            }
        }
    }
​
    // 状态压缩 DP，dp[mask][cur] 表示访问过 mask 里的所有客户后，停在 cur 的最短路径
    dp := make([][]int, 1<<N)
    for i := range dp {
        dp[i] = make([]int, N+1)
        for j := range dp[i] {
            dp[i][j] = math.MaxInt32
        }
    }
    dp[0][0] = 0 // 从起点出发
​
    for mask := 0; mask < (1 << N); mask++ {
        for cur := 0; cur <= N; cur++ {
            if dp[mask][cur] == math.MaxInt32 {
                continue
            }
            for next := 0; next <= N; next++ {
                if graph[cur][next] == -1 {
                    continue
                }
                if next == 0 {
                    dp[mask][next] = min(dp[mask][next], dp[mask][cur]+graph[cur][next])
                } else {
                    nextMask := mask | (1 << (next - 1))
                    dp[nextMask][next] = min(dp[nextMask][next], dp[mask][cur]+graph[cur][next])
                }
            }
        }
    }
​
    // 计算最终结果，遍历所有可能的终点
    end := (1 << N) - 1
    res := math.MaxInt32
    for i := 0; i <= N; i++ {
        if dp[end][i] != math.MaxInt32 && graph[i][0] != -1 {
            res = min(res, dp[end][i]+graph[i][0])
        }
    }
​
    // 输出结果
    fmt.Println(res)
}
